"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[9026],{5588(e){e.exports=JSON.parse('{"title":"\uc6f9 \uc5d0\ub514\ud130 \ub80c\ub354\ub9c1\uc744 \uc0c8\ub85c \uad6c\ucd95\ud55c \uc774\uc720","date":"2025-02-20","coverUrl":"/kudzu-based-bench/assets/notion/684f0c83f64b0d34.png","html":"<h2 data-notion-block-id=\\"19ce548d-8a8e-80ff-b5b2-c53340c489db\\" id=\\"19ce548d-8a8e-80ff-b5b2-c53340c489db\\">\uc6f9 \uc5d0\ub514\ud130 \ub80c\ub354\ub9c1\uc744 \uc0c8\ub85c \uad6c\ucd95\ud55c \uc774\uc720</h2><a href=\\"https://smoores.dev/post/why_i_rebuilt_prosemirror_view/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://smoores.dev/post/why_i_rebuilt_prosemirror_view/</a><p data-notion-block-id=\\"19ce548d-8a8e-806d-8955-db93b34bfa47\\">PromiseMirror \uc6f9 \uc5d0\ub514\ud130\ub294 \ud6cc\ub96d\ud558\uc9c0\ub9cc React \ub80c\ub354\ub9c1\uacfc \ucda9\ub3cc\ud558\ub294 \uc774\uc720\ub97c \ucc28\uadfc\ucc28\uadfc \uc124\uba85\ud558\uace0 view \ub85c\uc9c1\uc744 \ub2e4\uc2dc \ub9cc\ub4dc\ub294 \uac83\uc73c\ub85c \ud574\uacb0\ud55c \uac83\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. React \ub80c\ub354\ub9c1\uc744 \uc9da\uc5b4\ubcf4\uba74\uc11c \uc5b4\ub5a4 \ubd80\ubd84\uc774 \ucda9\ub3cc\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ubbc0\ub85c, React UI\uc744 \ub2e4\ub978 \ub80c\ub354\ub9c1\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc640 \ud569\uccd0\uc57c \ud560 \uacbd\uc6b0 \uc5b4\ub5bb\uac8c \ub300\uc751\ud574\uc57c \ud560\uc9c0, \ud639\uc740 \uc694\uad6c\uc0ac\ud56d\uc740 \uc5b4\ub5bb\uac8c \ud30c\uc545\ud574\uc57c \ud560\uc9c0 \uc798 \uc124\uba85\ud574\uc8fc\ubbc0\ub85c \ubcf4\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"19ce548d-8a8e-802f-a1e3-c706b27831d6\\" id=\\"19ce548d-8a8e-802f-a1e3-c706b27831d6\\">2025\ub144 \uc6f9 \uc5d0\ub514\ud130 \ub458\ub7ec\ubcf4\uae30</h2><a href=\\"https://liveblocks.io/blog/which-rich-text-editor-framework-should-you-choose-in-2025\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://liveblocks.io/blog/which-rich-text-editor-framework-should-you-choose-in-2025</a><p data-notion-block-id=\\"19ce548d-8a8e-8061-960a-d2ff1702facf\\">\uc218\ub9ce\uc740 \uc6f9 \uc5d0\ub514\ud130\ub97c \uae30\ubc18 \ub77c\uc774\ube0c\ub7ec\ub9ac, \ud65c\uc6a9\ubc29\uc2dd, \ud611\uc5c5\u2026 \uc5ec\ub7ec \uae30\uc900\uc744 \ubc14\ud0d5\uc73c\ub85c \uc7a5\ub2e8\uc810\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc6f9 \uc5d0\ub514\ud130\ub97c \uace0\ubbfc\ud560 \uacbd\uc6b0 \uadf8\ub0e5 Tiptap\uc744 \uc0ac\uc6a9\ud560 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uae00\uc5d0 \uc4f0\uc778 \uc7a5\ub2e8\uc810\uc744 \ube44\uad50\ud574\uc11c \uc801\uc6a9\ud574\ubcf4\ub294 \uac83\uc744 \uace0\ub824\ud574\ubcf4\uc138\uc694. \uc704\uc5d0\uc11c \uc18c\uac1c\ud55c PromiseMirror\ub3c4 \uc7a5\ub2e8\uc810\uc744 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"19ce548d-8a8e-804b-b2c1-c081649fb118\\" id=\\"19ce548d-8a8e-804b-b2c1-c081649fb118\\">CSS nesting \uc798 \uc0ac\uc6a9\ud558\uae30</h2><a href=\\"https://piccalil.li/blog/css-nesting-use-with-caution/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/css-nesting-use-with-caution/</a><p data-notion-block-id=\\"19ce548d-8a8e-80ed-9735-fa1138518058\\">\ucd5c\uc2e0 \uae30\ub2a5\uc778 CSS nesting\uc740 Sass/SCSS\uc640 \uc791\ub3d9 \ubc29\uc2dd\uc774 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0, CSS \uc804\ucc98\ub9ac\uae30\ub97c \uc0ac\uc6a9\ud560 \ub54c\uc5d0\ub294 <code>&#x26;</code>\uc744 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud588\ub294\uc9c0, Native CSS nesting\uc740 \uc791\ub3d9\ubc29\uc2dd\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0, \uc0ac\uc6a9\ud558\uae30 \uc704\ud574 \uc8fc\uc758\ud574\uc57c \ud560 \uc810\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"19ce548d-8a8e-803b-8212-cc6c9892a549\\" id=\\"19ce548d-8a8e-803b-8212-cc6c9892a549\\">2024\ub144\uc758 React \ub3cc\uc544\ubcf4\uae30</h2><a href=\\"https://2024.stateofreact.com/en-US/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2024.stateofreact.com/en-US/</a><p data-notion-block-id=\\"19ce548d-8a8e-803b-b49d-dee00d28fae4\\">React\uc5d0\uc11c\ub294 \uac00\uc7a5 \ud070 React 19/React \ucef4\ud30c\uc77c\ub7ec \ucd9c\uc2dc, \uadf8\ub9ac\uace0 <code>&#x3C;Suspense></code>\uc758 \ubc1c\uc804\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. React \uc0ac\uc6a9\uc790\uac00 \uc5b4\ub5a4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \uac83\uc744 \uc120\ud638\ud558\ub294\uc9c0 \uc54c \uc218 \uc788\ub294 \uc124\ubb38 \uacb0\uacfc\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"19ce548d-8a8e-80b9-9cdd-dd7b166e6267\\" id=\\"19ce548d-8a8e-80b9-9cdd-dd7b166e6267\\">ESM\ub9cc \uc0ac\uc6a9\ud558\uae30</h2><a href=\\"https://antfu.me/posts/move-on-to-esm-only\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://antfu.me/posts/move-on-to-esm-only</a><p data-notion-block-id=\\"198e548d-8a8e-80d9-9cb0-fbe32aa51eb8\\">ESM\uacfc CommonJS\ub97c \ub3d9\uc2dc\uc5d0 \uc81c\uacf5\ud558\uc9c0 \uc54a\uace0 ESM\ub9cc \uc81c\uacf5\ud558\uae30\ub85c \ud55c \uc774\uc720\uc640 \uc5b8\uc81c ESM\ub9cc \uc0ac\uc6a9\ud558\ub3c4\ub85d \uc804\ud658\ud574\uc57c \ud560\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 <a href=\\"https://bun.sh/blog/commonjs-is-not-going-away\\">Bun\uc5d0\uc11c CommonJS\ub294 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4</a>\uba70 \uc7a5\uc810\uc744 \uc18c\uac1c\ud588\uc9c0\ub9cc\u2026 <a href=\\"https://socket.dev/blog/require-esm-backported-to-node-js-20\\">\ucd5c\uc2e0 Node.js\uc5d0\uc11c </a><a href=\\"https://socket.dev/blog/require-esm-backported-to-node-js-20\\"><code>require(esm)</code></a><a href=\\"https://socket.dev/blog/require-esm-backported-to-node-js-20\\">\uc744 \uc9c0\uc6d0</a>\ud558\uace0, ESM\uc774 \ud45c\uc900\uc778 \ud604\uc7ac \uc124\uc815\uc774 \uc5b4\ub835\uae34 \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"19ce548d-8a8e-807f-9664-c624e98ff3b6\\" id=\\"19ce548d-8a8e-807f-9664-c624e98ff3b6\\">TypeScript\uc640 ESLint\uac00 \ucd94\uad6c\ud558\ub294 \ubc29\ud5a5</h2><a href=\\"https://eslint.org/blog/2025/01/differences-between-eslint-and-typescript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://eslint.org/blog/2025/01/differences-between-eslint-and-typescript/</a><p data-notion-block-id=\\"198e548d-8a8e-80b9-a05f-d845f923395d\\">\ub450 \uac00\uc9c0 \ubaa8\ub450 \uc815\uc801 \ubd84\uc11d \ud14c\uc2a4\ud2b8 \ub3c4\uad6c\uc9c0\ub9cc, ESLint\ub294 \ub9b0\ud130\ub85c\uc11c, TypeScript\ub294 \uc720\ud615 \uac80\uc0ac\uae30\ub85c\uc11c \uae30\ub2a5\uc774 \ub2e4\ub985\ub2c8\ub2e4. \ub450 \uae30\ub2a5\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0, \uae30\ub2a5\uc758 \uc5b4\ub290 \ubd80\ubd84\uc774 \uacb9\uce58\ub294 \uc601\uc5ed\uc774 \uc788\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"19ce548d-8a8e-8052-ab07-ce3f69be3b12\\" id=\\"19ce548d-8a8e-8052-ab07-ce3f69be3b12\\">\uc6f9 \ud655\uc7a5 \uae30\ub2a5 \uae30\ubcf8 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://chenhuijing.com/blog/learning-web-extensions\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://chenhuijing.com/blog/learning-web-extensions</a><p data-notion-block-id=\\"19ce548d-8a8e-80a8-b400-d75ba49e2024\\">\uc6f9 \ud655\uc7a5 \uae30\ub2a5\uc744 \ub9cc\ub4e4\uae30 \uc804\uc5d0 \uc54c\uc544\uc57c \ud560 \uac1c\ub150\ub4e4\uc744 \uac00\ubccd\uac8c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"19ce548d-8a8e-801f-a9a9-ff50aa2c045d\\" id=\\"19ce548d-8a8e-801f-a9a9-ff50aa2c045d\\">\ucc3d\uc758\uc801\uc778 WebGL \uc0ac\uc6a9\ubc95</h2><a href=\\"https://blog.maximeheckel.com/posts/post-processing-as-a-creative-medium/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.maximeheckel.com/posts/post-processing-as-a-creative-medium/</a><p data-notion-block-id=\\"198e548d-8a8e-8043-b7e3-c69586935284\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/43f27c92-8790-48e3-904c-82a7fab89e70#aa840b2b-5df0-450e-971e-474bee046564\\">\ub808\ud2b8\ub85c \ud6a8\uacfc \uad6c\ud604\ud558\uae30</a>\uc758 \uc800\uc790\uac00 \uc5b4\ub5bb\uac8c \uc601\uac10\uc744 \ubc1b\uc544 WebGL\uc744 \uc0ac\uc6a9\ud574\uc11c \uc5ec\ub7ec\uac00\uc9c0 \uc790\uc2e0\ub9cc\uc758 \uc791\uc5c5\ubb3c\uc744 \uad6c\ud604\ud588\ub294\uc9c0\ub97c \uacf5\uc720\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"19ce548d-8a8e-80b0-938f-f5cb111f18a1\\" id=\\"19ce548d-8a8e-80b0-938f-f5cb111f18a1\\">\uc0c8\ub85c\uc6b4 \uc5d4\uc9c4 \uad6c\ud604\ud558\uae30</h2><a href=\\"https://trynova.dev/blog/internals-of-nova-part-1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://trynova.dev/blog/internals-of-nova-part-1</a><a href=\\"https://www.youtube.com/watch?v=_uD2pijcSi4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=_uD2pijcSi4</a><p data-notion-block-id=\\"199e548d-8a8e-80ad-9c16-c6fd4a0f69df\\">\uc0c8\ub85c\uc6b4 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8 \uc5d4\uc9c4\uc778 nova\ub97c \uc18c\uac1c\ud558\ub294 \uae00, BoaJS\ub97c \uc18c\uac1c\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \uae00\uc740 nova \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8 \uc5d4\uc9c4\uc744 \uc18c\uac1c\ud558\uba70 ECMAScript \uc0ac\uc591\uc5d0 \uc788\ub294 \uac1d\uccb4\uc640 \uae30\uc874 \uc5d4\uc9c4\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uc774\ub97c \ud574\uc11d\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uc2dc\ub9ac\uc988 \uae00\uc785\ub2c8\ub2e4. \ub450 \ubc88\uc9f8 \uc601\uc0c1\uc740 Rust\ub85c JS \uc5d4\uc9c4\uc744 \ucc98\uc74c\ubd80\ud130 \ub9cc\ub4e4\uba74\uc11c JS\uc758 \uad6c\ubb38\ubd84\uc11d \uacfc\uc815, \ub809\uc2dc\uceec \ud658\uacbd\uc5d0 \ub300\ud574 \uc18c\uac1c\ud558\uace0, \ucd5c\uc2e0 \uc5d4\uc9c4\ub4e4\uc774 \uad6c\ubb38 \ubd84\uc11d\uc744 \ud558\uae30 \uc704\ud574 \uc801\uc6a9\ud55c \uae30\uc220\ub4e4\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"19ce548d-8a8e-80c1-bb36-e7fe19e0c8ef\\" id=\\"19ce548d-8a8e-80c1-bb36-e7fe19e0c8ef\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c</h2><a href=\\"https://nextjournal.com/dubroy/ohm-parsing-made-easy\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjournal.com/dubroy/ohm-parsing-made-easy</a><p data-notion-block-id=\\"1a1e548d-8a8e-8057-89fa-f496ab4868f4\\">\ud30c\uc2f1\uc744 \ub3c4\uc640\uc8fc\ub294 \ub3c4\uad6c\uc778 Ohm \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4. Ohm \uc5b8\uc5b4\ub97c \uc0ac\uc6a9\ud574\uc57c \ud558\uc9c0\ub9cc, \ud30c\uc2f1 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ube60\ub974\uac8c \uc81c\uc791\ud574\uc57c \ud560 \ub54c \ub3c4\uc6c0\uc774 \ub420 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</p>"}')}}]);